%[text] # Parameters
%[text] ![](text:image:73c2)
%[text] Fig. 1: User position coordinates according to \[1\].
%[text] #### Registered variables
LoggedSignals = struct();%signals that are updated during training or deployment, used for transfering between episodes
% Placeholders
LoggedSignals.h = [];%channel impulse response
EnvPars = struct();%signals that are constant during training and deployment

%[text] #### Transmission parameters
EnvPars.fc=28*10^9;%transmission frequency
EnvPars.BW = 400*10^6;%bandwidth, see [5, Tab. 6-1]
EnvPars.lambda=physconst('LightSpeed')/EnvPars.fc; %wavelength
EnvPars.k0=2*pi/EnvPars.lambda; %wavenumber

%[text] #### Channel parameters
%defining the hall dimensions in accordance with Table 6.1-1 pp. 18 in [10] TR 38857-h00
EnvPars.L_hall= 120; % length of factory hall in m
EnvPars.W_hall= 60; %width of hall
EnvPars.H_hall= 10; %height (ceiling), check whether H_hall=EnvPars.heigth_RM_m

EnvPars.fc_GHz = EnvPars.fc/1e9;

% Hall geometry required by the InF delay-spread formula
EnvPars.V_hall = EnvPars.L_hall * EnvPars.W_hall * EnvPars.H_hall;

EnvPars.S_hall = 2 * ( ...
    EnvPars.L_hall*EnvPars.W_hall + ...
    EnvPars.L_hall*EnvPars.H_hall + ...
    EnvPars.W_hall*EnvPars.H_hall);

% Delay spread: lgDS = log10(DS/1 second)
EnvPars.mu_lgDS = ...
    log10(26*(EnvPars.V_hall/EnvPars.S_hall) + 14) ...
    - 9.35;

EnvPars.sigma_lgDS = 0.15;

% Large-scale angular spreads
% lgAS = log10(AS/1 degree)
EnvPars.mu_lgASD    = 1.56;
EnvPars.sigma_lgASD = 0.25;

EnvPars.mu_lgASA = ...
    -0.18*log10(1 + EnvPars.fc_GHz) + 1.78;

EnvPars.sigma_lgASA = ...
    0.12*log10(1 + EnvPars.fc_GHz) + 0.20;

EnvPars.mu_lgZSA = ...
    -0.20*log10(1 + EnvPars.fc_GHz) + 1.50;

EnvPars.sigma_lgZSA = 0.35;

% Table 7.5-11
EnvPars.mu_lgZSD    = 1.35;
EnvPars.sigma_lgZSD = 0.35;

% Rician K-factor in dB
EnvPars.mu_K_dB    = 10;
EnvPars.sigma_K_dB = 8;
% EnvPars.mu_K_dB    = 7;
% EnvPars.sigma_K_dB = 8;

KR_dB = EnvPars.mu_K_dB + ...
            EnvPars.sigma_K_dB*randn;

EnvPars.KR = 10.^(KR_dB/10);

EnvPars.Nc   = 25;
EnvPars.Mray = 20;

% Delay-distribution proportionality factor
EnvPars.rTau = 2.7;

% Per-cluster shadowing standard deviation
EnvPars.clusterShadowingStd_dB = 4;

% Intra-cluster angular spreads from Table 7.5-6 Part-3
%for arrival angles
EnvPars.clusterASD_deg = 5;
EnvPars.clusterASA_deg = 8;
EnvPars.clusterZSA_deg = 9;

EnvPars.rayOffsetAlpha = [ ...
   -0.0447,  0.0447, ...
   -0.1413,  0.1413, ...
   -0.2492,  0.2492, ...
   -0.3715,  0.3715, ...
   -0.5129,  0.5129, ...
   -0.6797,  0.6797, ...
   -0.8844,  0.8844, ...
   -1.1481,  1.1481, ...
   -1.5195,  1.5195, ...
   -2.1551,  2.1551];

% Controlled-SNR experiment
EnvPars.normalizeH = true;

%[text] #### RECONFIGURABLE METASURFACE  Sm  
%[text] Placed in the XmYm plane
% [4,Sec. II-A] simulation: 20 x 20 unit cells of lambda/2 x lambda/2.
% [4,Sec. III]  experiment: 13 x 13 unit cells, 300 x 300 mm aperture, 2-bit.
EnvPars.Nx_RM        = 20;                % number of unit cells along xm
EnvPars.Ny_RM        = 20;                % number of unit cells along ym
EnvPars.Nel_RM = EnvPars.Nx_RM*EnvPars.Ny_RM %[output:5c8e7473]
EnvPars.dx_RM        = EnvPars.lambda/2;          % [m] unit-cell pitch along xm
EnvPars.dy_RM        = EnvPars.lambda/2;          % [m] unit-cell pitch along ym
EnvPars.heigth_RM_m  = 5.0;              % [m] ceiling height of the RM above the floor (4 to 8 m)
EnvPars.pos_RM = [0; 0; EnvPars.heigth_RM_m];

% Phase resolution of the RM.
%   Inf -> continuous phase          ([4,Sec. II-A], the idealised simulation)
%   2   -> 2-bit {0,90,180,270} deg  ([4,Sec. III], the fabricated prototype)
phaseBits_RM = Inf;


%  PROBE ANTENNA  (single element in the XaYa plane, phaseless readout)

% [4,Sec. II-A]: probe at (0, 0, 10*lambda).  [4,Sec. III]: za = 200 mm.
xa_nom   = 0;                     % [m] nominal probe position used to DESIGN M(.)
ya_nom   = 0;                     % [m]
za_nom   = 10*EnvPars.lambda;             % [m]
 
% Actual probe position used in the FORWARD propagation. Setting these
% different from the nominal values reproduces the mismatch study of Fig. 8
% (phase centre of the horn not at the assumed point).
xa_act   = xa_nom;                % [m]
ya_act   = ya_nom;                % [m]
za_act   = za_nom;                % [m]

%[text] #### User position

%% ------------------------------------------------------------------ %%
%  4. POINT SOURCES {Pn} -- INDOOR CEILING-MOUNTED DEPLOYMENT
%% ------------------------------------------------------------------ %%
% The RM is mounted flat on the ceiling, boresight pointing straight down at
% the floor. Sources (user devices) are given in room coordinates:
%   x, y  = horizontal offset from the point on the floor directly below the RM
%   EnvPars.srcHeight_m = height of the device above the floor

 
srcX_m       = [ 1.0, -1.5,  2.5, -3.0];   % [m] horizontal offset, x
srcY_m       = [ 1.5,  1.0, -2.0, -1.0];   % [m] horizontal offset, y
EnvPars.srcHeight_m  = [ 1.0,  1.0,  1.0,  1.0];   % [m] device height above the floor
srcAmp       = [ 1,    1,    1,    1  ];   % complex excitation of each source
 
% --- derived spherical coordinates (do not edit) ---------------------------
% theta = elevation from the RM boresight, phi = azimuth in the XmYm plane,
% consistent with Fig. 1(b) and with
%     kx_pn = k*sin(theta)*cos(phi),   ky_pn = k*sin(theta)*sin(phi).
srcZ_m      = EnvPars.heigth_RM_m - EnvPars.srcHeight_m(:).';            % z_pn, vertical drop
srcRange_m  = sqrt(srcX_m.^2 + srcY_m.^2 + srcZ_m.^2);
srcThetaDeg = rad2deg(acos(srcZ_m ./ srcRange_m));
srcPhiDeg   = mod(rad2deg(atan2(srcY_m, srcX_m)), 360);
%[text] #### Noise parameters
% Noise and interference parameters
noiseFigure = 7;                             % dB see [1, Tab. 6-1]
thermalNoiseDensity = -174;                  % dBm/Hz [11, Tab. 5, entry (14)]
%Interference noise
rxInterfDensity = -165.7;                    % dBm/Hz, see [3]
rxInterfDensity = -Inf;                    % no interference noise

% Calculate the corresponding noise power
% Receiver thermal noise density including noise figure
rxNoiseDensity = thermalNoiseDensity + noiseFigure;   % dBm/Hz

% Sum noise and interference in linear mW/Hz
totalNoiseDensity_dBHz = 10*log10(10^((rxNoiseDensity-30)/10) + 10^((rxInterfDensity-30)/10));

% Total noise power over bandwidth BW
noisePower_dB = totalNoiseDensity_dBHz + 10*log10(EnvPars.BW);
%[text] #### Plotting parameters
font=20;
plotGeom       = true;            % 3-D room geometry sketch, cf. Fig. 1(a)
% All POSITIONS in that sketch are true metric room coordinates. Only the
% DRAWN SIZE of the metasurface aperture and the probe horn is magnified, so
% that a 107 mm aperture stays visible next to a 4 m ceiling.
%   'auto'  -> aperture drawn at ~15% of the room's horizontal extent
%   numeric -> explicit magnification factor (1 = true size)
geomMagnify    = 'auto';
plotMap        = true;            % sine-space |Ea|^2 map (cf. Fig. 3c-d, Fig. 4)
plotCut        = true;            % 1-D profile through the strongest peak (cf. Fig. 3e-f)
plotTheory     = true;            % overlay the closed-form Dirichlet prediction
plotDynRangeDB = 30;
verboseFlag    = true;
saveTag        = '';              % non-empty -> results saved as LiAOA_<tag>.mat

% AOA scan grid for the Li2024 phaseless measurement.
% Fig. 3(c) uses polar coordinates: theta is radial and phi is angular.
thetaScanDeg = 0:1:80;            % [deg] trial elevation angles
phiScanDeg   = 0:1:359;           % [deg] trial azimuth angles
 
%% ------------------------------------------------------------------ %%
%  9. DERIVED QUANTITIES  (do not edit)
%% ------------------------------------------------------------------ %%
Dx_RM     = EnvPars.Nx_RM * EnvPars.dx_RM;        % [m] aperture size along xm
Dy_RM     = EnvPars.Ny_RM * EnvPars.dy_RM;        % [m] aperture size along ym
dA_RM     = EnvPars.dx_RM * EnvPars.dy_RM;        % [m^2] area weight per unit cell
res3dBdeg = rad2deg(0.886*EnvPars.lambda/max(Dx_RM,Dy_RM));  % [1,Sec. II-A, after Ref. [39]]
Rff_RM    = 2*hypot(Dx_RM,Dy_RM)^2 / EnvPars.lambda;         % [m] Fraunhofer distance
%[text] ## References
%[text] \[1\] F. Munier, Y. Guo, and R. Da, "Study on NR Positioning Enhancements (Release 17)," 3rd Generation Partnership Project, Sophia Antipolis, France, Technical Report (TR) TR 38.857 V17.0.0, Mar. 2021
%[text] \[2\] ETSI, "Reconfigurable Intelligent Surfaces (RIS); Communication Models, Channel Models, Channel Estimation and Evaluation Methodology," European Telecommunications Standards Institute, GR RIS 003 V1.1.1,Jun. 2023 
%[text] \[3\] WLAN PPDU Structure, [https://de.mathworks.com/help/wlan/gs/dmg-ppdu-structure.html](https://de.mathworks.com/help/wlan/gs/dmg-ppdu-structure.html)
%[text] \[4\] W. Li, N. Wang, and J. Qi, "Direct Angle of Arrival (AOA) Estimation Using a Metasurface Antenna With Single Frequency Phaseless Measurements Obeyed Schwarz Inequality," IEEE Transactions on Microwave Theory and Techniques, vol. 72, no. 4, pp. 2677–2685, Apr. 2024, doi: 10.1109/TMTT.2023.3314063.  
%[text]  \[5\] F. Munier, Y. Guo, and R. Da, "Study on NR Positioning Enhancements (Release 17)," 3rd Generation Partnership Project, Sophia Antipolis, France, Technical Report (TR) TR 38.857 V17.0.0, Mar. 2021

